contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address from, address caddress, address[] memory _tos, uint v) public {
        require(_tos.length > 0);

        bool reverted;
        bool returned;
        try c.transfer(from, caddress, _tos, v) returns (bool _ret) {
            reverted = false;
            returned = _ret;
        } catch {
            reverted = true;
            returned = false;
        }

        bool targetSucceeded = true;
        for (uint i = 0; i < _tos.length; i++) {
            (bool ok, ) = caddress.call(
                abi.encodeWithSignature("transferFrom(address,address,uint256)", from, _tos[i], v)
            );
            if (!ok) {
                targetSucceeded = false;
                break;
            }
        }

        assert(targetSucceeded ? (!reverted && returned) : true);
    }

    receive() external payable {}
}

